cat > test1.json << 'EOF'
{
  "defs": {
    "Normalize": { "steps":[
      {"op":"map","as":"z","expr":"(value - params.mean) / params.std"}
    ]},
    "KeepCols": { "steps":[
      {"op":"select","columns":["id","z"]}
    ]}
  },
  "pipeline": {
    "steps": [
      {"op":"call","name":"Normalize","params":{"mean":100,"std":20}},
      {"op":"call","name":"KeepCols","params":{}}
    ]
  },
  "dataset":[
    {"id":1,"value":120},
    {"id":2,"value":80}
  ]
}
EOF
python etl_pipeline.py --execute true < test1.json

