cat > test_comprehensive.json << 'EOF'
{
  "defs": {
    "NormBand": {
      "steps": [
        {"op": "map", "as": "normalized", "expr": "(value - params.min) / (params.max - params.min)"}
      ]
    },
    "FilterHigh": {
      "steps": [
        {"op": "filter", "where": "normalized > params.threshold"}
      ]
    },
    "Pipeline": {
      "steps": [
        {"op": "call", "name": "NormBand", "params": {"min": 0, "max": 100}},
        {"op": "call", "name": "FilterHigh", "params": {"threshold": 0.5}},
        {"op": "select", "columns": ["id", "normalized"]}
      ]
    }
  },
  "pipeline": {
    "steps": [
      {"op": "call", "name": "Pipeline"}
    ]
  },
  "dataset": [
    {"id": 1, "value": 25},
    {"id": 2, "value": 75},
    {"id": 3, "value": 50}
  ]
}
EOF
echo "=== Comprehensive test: multi-level nested calls with params ===" && python etl_pipeline.py --execute true < test_comprehensive.json
